/* @lc app=leetcode id=2799 lang=kotlin */ class Solution { fun countCompleteSubarrays(nums: IntArray): Int = nums.toSet().size.let { D -> HashMap<Int, Int>().let { c -> nums.indices.fold(Triple(0, 0, 0)) { (r, ans, _), l -> generateSequence(r) { it + 1 }.takeWhile { c.size < D && it < nums.size }.onEach { c.merge(nums[it], 1) { a, b -> a + b } }.count().let { cnt -> (r + cnt).let { r2 -> (if (c.size == D) nums.size - r2 + 1 else 0).let { add -> c.merge(nums[l], -1) { a, b -> a + b }.also { if (it == 0) c.remove(nums[l]) }.let { Triple(r2, ans + add, 0) } } } } }.second } } }